-- COLVY V263 — LEGAL CONTENT (Australian-law Privacy Policy + Terms of Service)
--
-- Seeds the global (company_id IS NULL) privacy and terms pages shown at
-- colvy.com/privacy and colvy.com/terms. Content is professional, Australian
-- Privacy Act 1988 (Cth) / APP-aligned, and includes the operating entity,
-- ABN, registered address and contact email. Re-runnable: it replaces the
-- current global rows for these two slugs.

DELETE FROM legal_pages WHERE company_id IS NULL AND slug IN ('privacy','terms');

INSERT INTO legal_pages (company_id, slug, title, sections, updated_at, updated_by) VALUES
(NULL, 'privacy', $legal$Privacy Policy$legal$, $legal$[{"heading":"About this policy","body":"Colvy is operated by Wallets Way Pty Ltd (ACN 666 674 602, ABN 54 666 674 602), trading as ‘Colvy’ (‘Colvy’, ‘we’, ‘us’ or ‘our’). We are committed to protecting your privacy and handling your personal information in accordance with the Privacy Act 1988 (Cth) (the ‘Privacy Act’) and the Australian Privacy Principles (the ‘APPs’).\nThis Privacy Policy explains how we collect, use, hold, disclose and protect personal information when you use the Colvy website, applications and services (the ‘Service’), and how you can access, correct or complain about our handling of it.\nBy using the Service you agree to the collection and use of your personal information as described in this policy."},{"heading":"The personal information we collect","body":"Personal information is information or an opinion about an identified, or reasonably identifiable, individual. Depending on how you interact with us, we may collect:\n• Account and identity information — your name, business name, email address, phone number and login credentials.\n• Billing information — billing name, address and payment details. Card payments are processed by our payment provider; we do not store full card numbers on our own systems.\n• Customer and contact data — information you or your end-customers provide through the Service, such as names, email addresses, phone numbers, addresses, order history and the content of messages, calls and enquiries.\n• Communications — messages, call recordings, voicemails and support requests sent or received through the Service, where enabled.\n• Technical and usage data — IP address, device and browser type, pages viewed and similar analytics collected automatically.\n• Cookies and similar technologies, as described below."},{"heading":"How we collect personal information","body":"We collect personal information directly from you when you create an account, contact us, make a payment or use features of the Service.\nWe also collect information automatically as you use the Service, and from third parties and integrations you choose to connect — such as e-commerce, point-of-sale, messaging, telephony and listing platforms — where you have authorised that connection.\nWhere it is reasonable and practicable to do so, we will collect personal information directly from the individual concerned."},{"heading":"Why we collect, hold and use personal information","body":"We collect, hold and use personal information to:\n• provide, operate, maintain and improve the Service;\n• set up and administer your account and process payments;\n• enable the messaging, CRM, telephony and integration features you use;\n• respond to your enquiries and provide customer support;\n• send you service-related and, where permitted, marketing communications;\n• maintain the security and integrity of the Service and prevent fraud or misuse; and\n• comply with our legal obligations.\nWe only use personal information for the purpose for which it was collected, for a related purpose you would reasonably expect, or as otherwise permitted or required by law."},{"heading":"Customer data and your end-customers","body":"When you use Colvy to manage conversations, contacts and orders, you may upload or generate personal information about your own customers and contacts (‘Customer Data’). You are responsible for how that Customer Data is collected and used, and you control it. Colvy processes Customer Data on your behalf, in accordance with our agreement with you and this policy.\nYou are responsible for ensuring you have any necessary consents and a lawful basis to collect that data and to send communications (including SMS, email and calls) through the Service, and for complying with the Privacy Act, the Spam Act 2003 (Cth) and the Do Not Call Register Act 2006 (Cth) where applicable."},{"heading":"Disclosure of personal information","body":"We do not sell your personal information. We may disclose it to:\n• service providers and sub-processors who help us operate the Service, including cloud hosting and infrastructure, database, payment, email, SMS and telephony providers;\n• third-party platforms and integrations that you choose to connect to your account, at your direction;\n• professional advisers such as lawyers and accountants;\n• a purchaser or prospective purchaser in connection with a sale or restructure of our business; and\n• government, regulatory or law-enforcement bodies where required or authorised by law.\nWe take reasonable steps to ensure these parties handle personal information consistently with the Privacy Act."},{"heading":"Overseas disclosure","body":"Some of our service providers and infrastructure may store or process personal information outside Australia, including in the United States and other countries. Where we disclose personal information to overseas recipients, we take reasonable steps to ensure they handle it in accordance with the APPs, or that an exception under the Privacy Act applies. By using the Service, you acknowledge that your personal information may be stored or processed overseas."},{"heading":"Data security","body":"We take reasonable steps to protect personal information from misuse, interference and loss, and from unauthorised access, modification or disclosure. These steps include encryption of data in transit, access controls and authentication, the use of reputable infrastructure providers, and internal policies restricting access to personal information.\nNo method of transmission or storage is completely secure and we cannot guarantee absolute security. If we become aware of an eligible data breach that is likely to result in serious harm, we will respond in accordance with the Notifiable Data Breaches scheme under the Privacy Act, including notifying affected individuals and the Office of the Australian Information Commissioner (‘OAIC’) where required."},{"heading":"How long we keep your information","body":"We hold personal information only for as long as it is needed for the purposes described in this policy, or as required by law. When it is no longer required, we take reasonable steps to destroy or de-identify it. Where you close your account, we may retain certain information as necessary to comply with our legal obligations, resolve disputes and enforce our agreements."},{"heading":"Cookies and analytics","body":"We use cookies and similar technologies to keep you signed in, remember your preferences, and understand how the Service is used so we can improve it. You can control or disable cookies through your browser settings, although some features may not function properly without them."},{"heading":"Direct marketing","body":"We may send you marketing communications about our products and services where you would reasonably expect us to, or where you have consented. You can opt out at any time using the unsubscribe function in the message or by contacting us at support@colvy.com. We will action your request within a reasonable time."},{"heading":"Accessing and correcting your information","body":"You may request access to the personal information we hold about you, and ask us to correct it if it is inaccurate, out of date, incomplete, irrelevant or misleading. To make a request, contact us at support@colvy.com. We will respond within a reasonable period and may need to verify your identity first. In some circumstances we may decline a request as permitted by the Privacy Act, and if we do, we will explain why in writing."},{"heading":"Complaints","body":"If you have a concern or complaint about how we have handled your personal information, please contact us at support@colvy.com and we will investigate and respond. If you are not satisfied with our response, you may lodge a complaint with the Office of the Australian Information Commissioner (OAIC) at www.oaic.gov.au."},{"heading":"Changes to this policy","body":"We may update this Privacy Policy from time to time. The current version will always be available on our website, and the ‘last edited’ date above shows when it was most recently changed. Your continued use of the Service after a change means you accept the updated policy."},{"heading":"Contact us","body":"For any privacy question or request, contact:\nWallets Way Pty Ltd trading as Colvy\nABN 54 666 674 602\n5 Clunes Avenue, Dallas VIC 3047, Australia\nEmail: support@colvy.com"}]$legal$::jsonb, NOW(), 'support@colvy.com'),
(NULL, 'terms',   $legal$Terms of Service$legal$,   $legal$[{"heading":"Agreement to terms","body":"These Terms of Service (‘Terms’) govern your access to and use of the Colvy website, applications and services (the ‘Service’). The Service is provided by Wallets Way Pty Ltd (ACN 666 674 602, ABN 54 666 674 602), trading as ‘Colvy’ (‘Colvy’, ‘we’, ‘us’ or ‘our’).\nBy creating an account or using the Service, you agree to these Terms. If you use the Service on behalf of a business, you agree to these Terms on behalf of that business and confirm you have authority to do so. If you do not agree, you must not use the Service."},{"heading":"The Service","body":"Colvy provides a customer communication, CRM and related tools platform, including messaging, contacts, campaigns, telephony and integrations with third-party platforms. We may add, change or remove features from time to time to improve the Service."},{"heading":"Eligibility and accounts","body":"You must be at least 18 years old and able to form a legally binding contract to use the Service. You are responsible for the information you provide, for keeping your login credentials confidential, and for all activity under your account. Notify us immediately at support@colvy.com if you suspect any unauthorised use of your account."},{"heading":"Fees, billing and taxes","body":"Paid plans are billed in advance on a recurring basis (for example monthly or annually) according to the plan you select. Unless stated otherwise, fees are in Australian dollars and are inclusive of GST where applicable. Card payments are processed by our third-party payment provider.\nSubscriptions renew automatically for successive periods unless cancelled before the renewal date. You may cancel at any time, effective at the end of your current billing period. Except where required by the Australian Consumer Law or expressly stated, fees are non-refundable. We may change our fees on reasonable notice, with changes taking effect from your next billing period."},{"heading":"Acceptable use","body":"You agree not to use the Service to:\n• breach any law, or infringe the rights of others;\n• send unlawful, misleading, harassing or unsolicited communications, including in breach of the Spam Act 2003 (Cth) or the Do Not Call Register Act 2006 (Cth);\n• transmit malware or attempt to gain unauthorised access to the Service or its systems;\n• interfere with or disrupt the integrity or performance of the Service; or\n• resell or provide the Service to third parties except as permitted by us in writing.\nWe may suspend or limit access to protect the Service or other users."},{"heading":"Your data and privacy","body":"As between you and Colvy, you own the data you upload or generate through the Service (‘Your Data’), including data about your customers and contacts. You grant us a non-exclusive licence to host, process and use Your Data as reasonably necessary to provide and improve the Service.\nYou are responsible for Your Data and for ensuring you have all necessary rights and consents to collect it and to send communications (including SMS, email and calls, and any call recording) through the Service. Our handling of personal information is described in our Privacy Policy, which forms part of these Terms."},{"heading":"Third-party integrations","body":"The Service can connect to third-party products and platforms (for example e-commerce, point-of-sale, telephony, payment and listing platforms). Your use of those services is governed by their own terms and privacy policies. We are not responsible for third-party services and do not warrant their availability, accuracy or security. Connecting a third-party service is at your own risk."},{"heading":"Intellectual property","body":"The Service, including its software, design, text and branding, is owned by Colvy or its licensors and is protected by intellectual property laws. We grant you a limited, non-exclusive, non-transferable right to use the Service in accordance with these Terms. You must not copy, modify, reverse-engineer or create derivative works from the Service except to the extent permitted by law."},{"heading":"Availability and support","body":"We aim to keep the Service available and reliable, but we do not guarantee it will be uninterrupted or error-free. We may perform maintenance and may modify or discontinue parts of the Service. We provide support by email at support@colvy.com."},{"heading":"Australian Consumer Law","body":"Nothing in these Terms excludes, restricts or modifies any consumer guarantee, right or remedy you have under the Australian Consumer Law (‘ACL’) or other law that cannot lawfully be excluded. If our Service comes with guarantees that cannot be excluded under the ACL and we fail to meet them, our liability is limited (where permitted) to re-supplying the Service or paying the cost of having it re-supplied."},{"heading":"Warranties and limitation of liability","body":"To the maximum extent permitted by law, and subject to the Australian Consumer Law, the Service is provided ‘as is’ and ‘as available’, and we exclude all implied warranties. We are not liable for any indirect, incidental, special or consequential loss, or for loss of profits, revenue, data or goodwill.\nTo the maximum extent permitted by law, our total liability arising out of or in connection with the Service is limited to the amount you paid us for the Service in the twelve (12) months before the event giving rise to the liability."},{"heading":"Indemnity","body":"You agree to indemnify us against any claim, loss, liability or expense we suffer arising from your breach of these Terms, your misuse of the Service, Your Data, or the communications you send through the Service."},{"heading":"Suspension and termination","body":"You may stop using the Service and close your account at any time. We may suspend or terminate your access if you breach these Terms, fail to pay fees, or if we are required to do so by law. On termination your right to use the Service ends, and we may delete Your Data after a reasonable period, subject to any legal retention obligations."},{"heading":"Changes to these Terms","body":"We may update these Terms from time to time. The current version will always be available on our website, and the ‘last edited’ date above shows when it was most recently changed. If a change is material, we will take reasonable steps to notify you. Your continued use of the Service after a change means you accept the updated Terms."},{"heading":"Governing law","body":"These Terms are governed by the laws of the State of Victoria, Australia. You and Colvy submit to the non-exclusive jurisdiction of the courts of Victoria and the courts competent to hear appeals from them."},{"heading":"Contact us","body":"Wallets Way Pty Ltd trading as Colvy\nABN 54 666 674 602\n5 Clunes Avenue, Dallas VIC 3047, Australia\nEmail: support@colvy.com"}]$legal$::jsonb, NOW(), 'support@colvy.com');
